// specs/server/agent-runner.t27
// Agent Runner Specification
// Constitutional Law #4: De-Zig-fication - .t27 is source of truth
// Constitutional Law #5: De-Zig Strict - no new Rust business logic

module AgentRunner {
    use base::types;

    // ====================================================================
    // Agent Report
    // ====================================================================

    struct AgentReport {
        turns: u32,
        total_input_tokens: u64,
        total_output_tokens: u64,
        tool_call_count: u32,
        file_mod_count: u32,
        task_completed: bool,
        summary: str,
        duration_seconds: f64,
    }

    // ====================================================================
    // Tool System
    // ====================================================================

    struct ToolResult {
        output: str,
        is_complete: bool,
        duration_ms: u64,
        success: bool,
    }

    enum StopReason {
        EndTurn = 0,
        ToolUse = 1,
        MaxTokens = 2,
        Unknown = 3,
    }

    // ====================================================================
    // Agent State
    // ====================================================================

    struct AgentState {
        turn: u32,
        max_turns: u32,
        total_input_tokens: u64,
        total_output_tokens: u64,
        tool_call_counter: u32,
        task_completed: bool,
        completion_summary: str,
    }

    // ====================================================================
    // Agent Constants
    // ====================================================================

    const MAX_TURNS: u32 = 100;
    const MAX_TOOLS_CALLED: u32 = 256;
    const MAX_FILES_MODIFIED: u32 = 256;
    const DEFAULT_TIMEOUT_SECONDS: u32 = 120;
    const MAX_TOKEN_SUMMARY_LENGTH: u32 = 200;

    // ====================================================================
    // Agent Initialization
    // ====================================================================

    fn agent_state_init(max_turns: u32) -> AgentState {
        var state = AgentState{};
        state.turn = 0;
        state.max_turns = max_turns;
        state.total_input_tokens = 0;
        state.total_output_tokens = 0;
        state.tool_call_counter = 0;
        state.task_completed = false;
        return state;
    }

    fn agent_report_init() -> AgentReport {
        var report = AgentReport{};
        report.turns = 0;
        report.total_input_tokens = 0;
        report.total_output_tokens = 0;
        report.tool_call_count = 0;
        report.file_mod_count = 0;
        report.task_completed = false;
        report.duration_seconds = 0.0;
        return report;
    }

    // ====================================================================
    // Tool Execution
    // ====================================================================

    fn track_tool_call(state: AgentState, tool_name: str) -> AgentState {
        var new_state = state;
        new_state.tool_call_counter = state.tool_call_counter + 1;
        return new_state;
    }

    fn check_task_complete(result: ToolResult) -> bool {
        return result.is_complete;
    }

    // ====================================================================
    // Stop Reason Helpers
    // ====================================================================

    fn stop_reason_from_string(reason: str) -> StopReason {
        if reason == "end_turn" {
            return StopReason::EndTurn;
        }
        if reason == "tool_use" {
            return StopReason::ToolUse;
        }
        if reason == "max_tokens" {
            return StopReason::MaxTokens;
        }
        return StopReason::Unknown;
    }

    fn stop_reason_to_string(reason: StopReason) -> str {
        if reason == StopReason::EndTurn {
            return "end_turn";
        }
        if reason == StopReason::ToolUse {
            return "tool_use";
        }
        if reason == StopReason::MaxTokens {
            return "max_tokens";
        }
        return "unknown";
    }

    // ====================================================================
    // Token Tracking
    // ====================================================================

    fn add_tokens(state: AgentState, input_tokens: u64, output_tokens: u64) -> AgentState {
        var new_state = state;
        new_state.total_input_tokens = state.total_input_tokens + input_tokens;
        new_state.total_output_tokens = state.total_output_tokens + output_tokens;
        return new_state;
    }

    fn total_tokens(state: AgentState) -> u64 {
        return state.total_input_tokens + state.total_output_tokens;
    }

    // ====================================================================
    // String Helpers
    // ====================================================================

    fn truncate_string(s: str, max: u32) -> str {
        return s;
    }

    // ====================================================================
    // Turn Management
    // ====================================================================

    fn next_turn(state: AgentState) -> AgentState {
        var new_state = state;
        new_state.turn = state.turn + 1;
        return new_state;
    }

    fn should_continue(state: AgentState) -> bool {
        return state.turn < state.max_turns;
    }

    // ====================================================================
    // Report Building
    // ====================================================================

    fn build_report(state: AgentState, duration_seconds: f64) -> AgentReport {
        var report = agent_report_init();
        report.turns = state.turn;
        report.total_input_tokens = state.total_input_tokens;
        report.total_output_tokens = state.total_output_tokens;
        report.task_completed = state.task_completed;
        report.summary = state.completion_summary;
        report.duration_seconds = duration_seconds;
        return report;
    }

    // ====================================================================
    // Tests
    // ====================================================================

    test "agent_state_init" {
        var state = agent_state_init(10);
        assert(state.turn == 0);
        assert(state.max_turns == 10);
        assert(state.total_input_tokens == 0);
        assert(state.total_output_tokens == 0);
        assert(state.task_completed == false);
    }

    test "agent_report_init" {
        var report = agent_report_init();
        assert(report.turns == 0);
        assert(report.task_completed == false);
        assert(report.duration_seconds == 0.0);
    }

    test "stop_reason_conversion" {
        assert(stop_reason_from_string("end_turn") == StopReason::EndTurn);
        assert(stop_reason_from_string("tool_use") == StopReason::ToolUse);
        assert(stop_reason_from_string("max_tokens") == StopReason::MaxTokens);
        assert(stop_reason_from_string("unknown") == StopReason::Unknown);
    }

    test "token_tracking" {
        var state = agent_state_init(10);
        state = add_tokens(state, 100, 50);
        assert(state.total_input_tokens == 100);
        assert(state.total_output_tokens == 50);
        assert(total_tokens(state) == 150);
    }

    test "turn_management" {
        var state = agent_state_init(10);
        assert(should_continue(state) == true);
        state = next_turn(state);
        assert(state.turn == 1);
    }

    test "constants" {
        assert(MAX_TURNS == 100);
        assert(MAX_TOOLS_CALLED == 256);
        assert(MAX_FILES_MODIFIED == 256);
        assert(DEFAULT_TIMEOUT_SECONDS == 120);
        assert(MAX_TOKEN_SUMMARY_LENGTH == 200);
    }

    // ====================================================================
    // Invariants
    // ====================================================================

    invariant "turns_non_negative" {
        var state = agent_state_init(10);
        assert(state.turn >= 0);
    }
}

// specs/account/schema.t27
// Account Types Specification
// phi^2 + 1/phi^2 = 3 | TRINITY

module Account {
    use base::types;

    // ====================================================================
    // Account Identifiers
    // ====================================================================

    // AccountID uniquely identifies an account
    struct AccountID(str);

    // OrgID uniquely identifies an organization
    struct OrgID(str);

    // AccessToken represents an OAuth access token
    struct AccessToken(str);

    // RefreshToken represents an OAuth refresh token
    struct RefreshToken(str);

    // DeviceCode represents an OAuth device code
    struct DeviceCode(str);

    // UserCode represents a user verification code
    struct UserCode(str);

    // ====================================================================
    // Account Info Types
    // ====================================================================

    // Info represents account information
    struct Info {
        id: AccountID,
        email: str,
        url: str,
        active_org_id: OrgID?,
    }

    // Org represents an organization
    struct Org {
        id: OrgID,
        name: str,
    }

    // Login represents a device code login session
    struct Login {
        code: DeviceCode,
        user: UserCode,
        url: str,
        server: str,
        expiry: u64,  // milliseconds
        interval: u64,  // milliseconds
    }

    // ====================================================================
    // Poll Result Types
    // ====================================================================

    // PollResult represents the result of polling for device auth
    enum PollResult {
        Success = 0,
        Pending = 1,
        Slow = 2,
        Expired = 3,
        Denied = 4,
        Error = 5,
    }

    // PollSuccess indicates successful authentication
    struct PollSuccess {
        email: str,
    }

    // PollPending indicates authentication is still pending
    struct PollPending {}

    // PollSlow indicates polling should slow down
    struct PollSlow {}

    // PollExpired indicates the device code has expired
    struct PollExpired {}

    // PollDenied indicates the user denied the request
    struct PollDenied {}

    // PollError indicates an error occurred
    struct PollError {
        cause: str,
    }

    // ====================================================================
    // Error Types
    // ====================================================================

    // AccountRepoError represents a repository error
    struct AccountRepoError {
        message: str,
        cause: str?,
    }

    // AccountServiceError represents a service error
    struct AccountServiceError {
        message: str,
        cause: str?,
    }

    // AccountError is a union of all account errors
    enum AccountError {
        Repo = 0,
        Service = 1,
    }

    // ====================================================================
    // Constants
    // ====================================================================

    const CLIENT_ID: str = "opencode-cli";
    const EAGER_REFRESH_THRESHOLD_MINUTES: u32 = 5;
    const DEFAULT_POLL_INTERVAL_MS: u64 = 5000;

    // ====================================================================
    // Helper Functions
    // ====================================================================

    // is_token_fresh checks if a token is fresh (not near expiry)
    fn is_token_fresh(token_expiry: u64?, now: u64) -> bool {
        // Token is fresh if it exists and expires after eager refresh threshold
        if (token_expiry == null) {
            return false;
        }
        var threshold_ms = (EAGER_REFRESH_THRESHOLD_MINUTES as u64) * 60 * 1000;
        return token_expiry > (now + threshold_ms);
    }

    // ====================================================================
    // Tests
    // ====================================================================

    test "account_id_creation" {
        var id = AccountID("user-123");
        assert(id.0 == "user-123");
    }

    test "org_id_creation" {
        var id = OrgID("org-456");
        assert(id.0 == "org-456");
    }

    test "access_token_creation" {
        var token = AccessToken("ghp_xxx");
        assert(token.0 == "ghp_xxx");
    }

    test "info_creation" {
        var info = Info {
            id = AccountID("user-123"),
            email = "user@example.com",
            url = "https://example.com",
            active_org_id = OrgID("org-456"),
        };
        assert(info.id.0 == "user-123");
        assert(info.email == "user@example.com");
    }

    test "org_creation" {
        var org = Org {
            id = OrgID("org-456"),
            name = "Acme Inc",
        };
        assert(org.name == "Acme Inc");
    }

    test "login_creation" {
        var login = Login {
            code = DeviceCode("device-code"),
            user = UserCode("ABCD-1234"),
            url = "https://example.com/auth",
            server = "https://example.com",
            expiry = 300000,  // 5 minutes
            interval = 5000,
        };
        assert(login.user.0 == "ABCD-1234");
        assert(login.expiry == 300000);
    }

    test "poll_result_enum_values" {
        assert(PollResult::Success as u32 == 0);
        assert(PollResult::Pending as u32 == 1);
        assert(PollResult::Slow as u32 == 2);
        assert(PollResult::Expired as u32 == 3);
        assert(PollResult::Denied as u32 == 4);
        assert(PollResult::Error as u32 == 5);
    }

    test "is_token_fresh_with_valid_expiry" {
        var expiry = (60 * 1000) + (10 * 60 * 1000);  // 10 minutes from now
        var now = 60 * 1000;  // 1 minute from now
        assert(is_token_fresh(expiry, now));
    }

    test "is_token_fresh_with_near_expiry" {
        var expiry = (60 * 1000) + (3 * 60 * 1000);  // 3 minutes from now
        var now = 60 * 1000;  // 1 minute from now
        assert(!is_token_fresh(expiry, now));
    }

    test "is_token_fresh_with_null_expiry" {
        var now = 60 * 1000;
        assert(!is_token_fresh(null, now));
    }

    test "is_token_fresh_with_expired_token" {
        var expiry = 30 * 1000;  // 30 seconds from now
        var now = 60 * 1000;  // 1 minute from now (token already expired)
        assert(!is_token_fresh(expiry, now));
    }

    test "constants_values" {
        assert(CLIENT_ID == "opencode-cli");
        assert(EAGER_REFRESH_THRESHOLD_MINUTES == 5);
        assert(DEFAULT_POLL_INTERVAL_MS == 5000);
    }
}

