// Project Management Specification
// Constitutional Law #4: De-Zig-fication - .t27 is source of truth
// Constitutional Law #5: De-Zig Strict - no new Rust business logic

module Project {
    use base::types;

    // ====================================================================
    // Project Structure
    // ====================================================================

    struct Project {
        id: str,
        name: str,
        path: str,
        created_at: u64,
        updated_at: u64,
        file_count: u32,
        current: bool,
    }

    struct FileEntry {
        path: str,
        content: str,
        modified: bool,
    }

    // ====================================================================
    // Project Manager
    // ====================================================================

    struct ProjectManager {
        projects: [32]Project,
        project_count: u32,
        current_project_id: str,
    }

    fn project_manager_init() -> ProjectManager {
        return ProjectManager{
            projects = [Project{}; 32],
            project_count = 0,
            current_project_id = "",
        };
    }

    // ====================================================================
    // Project Operations
    // ====================================================================

    fn create_project(mgr: *ProjectManager, name: str, path: str) -> Project {
        const id = "proj-" ++ name
        var project = Project{
            id = id,
            name = name,
            path = path,
            created_at = 0,
            updated_at = 0,
            file_count = 0,
            current = true,
        }
        if (mgr.project_count < 32) {
            mgr.projects[mgr.project_count] = project
            mgr.project_count = mgr.project_count + 1
            mgr.current_project_id = id
        }
        return project
    }

    fn get_project(mgr: ProjectManager, id: str) -> Project {
        var i: u32 = 0
        while (i < mgr.project_count) {
            if (mgr.projects[i].id == id) {
                return mgr.projects[i]
            }
            i = i + 1
        }
        return Project{id = "", name = "", path = "", created_at = 0, updated_at = 0, file_count = 0, current = false}
    }

    fn get_current_project(mgr: ProjectManager) -> Project {
        return get_project(mgr, mgr.current_project_id)
    }

    fn set_current_project(mgr: *ProjectManager, id: str) -> bool {
        var found: bool = false
        var i: u32 = 0
        while (i < mgr.project_count) {
            mgr.projects[i].current = (mgr.projects[i].id == id)
            if (mgr.projects[i].id == id) {
                found = true
                mgr.current_project_id = id
            }
            i = i + 1
        }
        return found
    }

    fn list_projects(mgr: ProjectManager) -> [32]Project {
        return mgr.projects
    }

    fn delete_project(mgr: *ProjectManager, id: str) -> bool {
        var found: bool = false
        var i: u32 = 0
        while (i < mgr.project_count) {
            if (mgr.projects[i].id == id) {
                found = true
            }
            if (found and i < mgr.project_count - 1) {
                mgr.projects[i] = mgr.projects[i + 1]
            }
            i = i + 1
        }
        if (found) {
            mgr.project_count = mgr.project_count - 1
            if (mgr.current_project_id == id) {
                mgr.current_project_id = ""
            }
        }
        return found
    }

    // ====================================================================
