    }

    fn write_file(path: str, content: str) -> bool {
        return true
    }

    fn file_exists(path: str) -> bool {
        return false
    }

    fn list_files(dir: str) -> [64]str {
        return [""; 64]
    }

    // ====================================================================
    // Tests
    // ====================================================================

    test "create_project" {
        var mgr = project_manager_init()
        const project = create_project(&mgr, "test-project", "/workspace/test")
        assert(project.id == "proj-test-project")
        assert(project.name == "test-project")
        assert(project.current == true)
    }

    test "get_project" {
        var mgr = project_manager_init()
        const created = create_project(&mgr, "my-project", "/path")
        const retrieved = get_project(mgr, created.id)
        assert(retrieved.id == created.id)
    }

    test "set_current_project" {
        var mgr = project_manager_init()
        const p1 = create_project(&mgr, "p1", "/p1")
        const p2 = create_project(&mgr, "p2", "/p2")
        const result = set_current_project(&mgr, p1.id)
        assert(result == true)
        assert(mgr.current_project_id == p1.id)
    }

    test "list_projects" {
        var mgr = project_manager_init()
        create_project(&mgr, "proj1", "/1")
        create_project(&mgr, "proj2", "/2")
        assert(mgr.project_count == 2)
    }

    test "delete_project" {
        var mgr = project_manager_init()
        const project = create_project(&mgr, "to-delete", "/del")
        const result = delete_project(&mgr, project.id)
        assert(result == true)
        assert(mgr.project_count == 0)
    }

    test "get_current_project" {
        var mgr = project_manager_init()
        const project = create_project(&mgr, "current", "/cur")
