// bus/pubsub.t27 — Publish/Subscribe Patterns
// Pub/sub interface for event-driven communication
// φ² + 1/φ² = 3 | TRINITY

module bus-pubsub;

// ============================================================================
// Imports
// ============================================================================

use tritype-base::usize;
use bus-schema::Event;
use bus-schema::Subscription;
use bus-schema::TopicPattern;
use bus-schema::BusState;
use bus-schema::topic_pattern_create;
use bus-schema::event_create;

// ============================================================================
// Constants
// ============================================================================

/// Default publish timeout in milliseconds
pub const DEFAULT_PUBLISH_TIMEOUT_MS : usize = 5000;

/// Default subscribe timeout in milliseconds
pub const DEFAULT_SUBSCRIBE_TIMEOUT_MS : usize = 5000;

/// Maximum pending publishes
pub const MAX_PENDING_PUBLISHES : usize = 10000;

/// Maximum topics per bus
pub const MAX_TOPICS : usize = 1000;

/// Default retry attempts for publish
pub const DEFAULT_PUBLISH_RETRIES : usize = 3;

/// Topic hierarchy separator
pub const TOPIC_SEPARATOR : [1]u8 = "/";

/// Topic wildcard for single level
pub const SINGLE_LEVEL_WILDCARD : [1]u8 = "+";

/// Topic wildcard for multi-level
pub const MULTI_LEVEL_WILDCARD : [1]u8 = "#";

// ============================================================================
// Types
// ============================================================================

/// Publish result
pub const PublishResult = struct {
    success : bool,
    event_id : usize,
    error : []u8,
};

/// Subscribe result
pub const SubscribeResult = struct {
    success : bool,
    subscription_id : usize,
    error : []u8,
};

/// Unsubscribe result
pub const UnsubscribeResult = struct {
    success : bool,
    subscriptions_removed : usize,
    error : []u8,
};

/// Topic tree node
pub const TopicNode = struct {
    topic : []u8,
    subscriptions : []Subscription,
    children : []TopicNode,
};

/// Pub/sub configuration
pub const PubSubConfig = struct {
    max_pending_publishes : usize,
    max_topics : usize,
    max_subscribers_per_topic : usize,
    enable_wildcards : bool,
};

/// Subscriber context
pub const SubscriberContext = struct {
    subscriber_id : []u8,
    topic_pattern : TopicPattern,
    callback : []u8,
};

/// Topic match result
pub const TopicMatchResult = struct {
    matches : bool,
    matched_topic : []u8,
    wildcard_matched : bool,
};

/// Bus info
pub const BusInfo = struct {
    state : BusState,
    topic_count : usize,
    subscriber_count : usize,
    pending_publish_count : usize,
};

/// Delivery queue
pub const DeliveryQueue = struct {
    events : []Event,
    capacity : usize,
    head : usize,
    tail : usize,
};

/// Pending publish
pub const PendingPublish = struct {
    event : Event,
    retries : usize,
    created_at : usize,
};

/// Topic hierarchy
pub const TopicHierarchy = struct {
    root : TopicNode,
    separator : []u8,
};

// ============================================================================
// Functions
// ============================================================================

/// Create publish result
pub fn publish_result_create(success: bool, event_id: usize) PublishResult {
    return PublishResult{
        .success = success,
        .event_id = event_id,
        .error = "",
    };
}

/// Create publish result with error
pub fn publish_result_error(error: []u8) PublishResult {
    return PublishResult{
        .success = false,
        .event_id = 0,
        .error = error,
    };
}

/// Create subscribe result
pub fn subscribe_result_create(success: bool, subscription_id: usize) SubscribeResult {
    return SubscribeResult{
        .success = success,
        .subscription_id = subscription_id,
        .error = "",
    };
}

/// Create subscribe result with error
pub fn subscribe_result_error(error: []u8) SubscribeResult {
    return SubscribeResult{
        .success = false,
        .subscription_id = 0,
        .error = error,
    };
}

/// Create unsubscribe result
pub fn unsubscribe_result_create(success: bool, removed: usize) UnsubscribeResult {
    return UnsubscribeResult{
        .success = success,
        .subscriptions_removed = removed,
        .error = "",
    };
}

/// Create unsubscribe result with error
pub fn unsubscribe_result_error(error: []u8) UnsubscribeResult {
    return UnsubscribeResult{
        .success = false,
        .subscriptions_removed = 0,
        .error = error,
    };
}

/// Create topic node
pub fn topic_node_create(topic: []u8) TopicNode {
    return TopicNode{
        .topic = topic,
        .subscriptions = &[_]Subscription{},
        .children = &[_]TopicNode{},
    };
}

/// Create pub/sub config
pub fn pubsub_config_default() PubSubConfig {
    return PubSubConfig{
        .max_pending_publishes = MAX_PENDING_PUBLISHES,
        .max_topics = MAX_TOPICS,
        .max_subscribers_per_topic = 100,
        .enable_wildcards = true,
    };
}

/// Create subscriber context
pub fn subscriber_context_create(subscriber_id: []u8, topic_pattern: TopicPattern, callback: []u8) SubscriberContext {
    return SubscriberContext{
        .subscriber_id = subscriber_id,
        .topic_pattern = topic_pattern,
        .callback = callback,
    };
}

/// Create topic match result
pub fn topic_match_result_create(matches: bool, topic: []u8) TopicMatchResult {
    return TopicMatchResult{
        .matches = matches,
        .matched_topic = topic,
        .wildcard_matched = false,
    };
}

/// Create bus info
pub fn bus_info_create(state: BusState) BusInfo {
    return BusInfo{
        .state = state,
        .topic_count = 0,
        .subscriber_count = 0,
        .pending_publish_count = 0,
    };
}

/// Create delivery queue
pub fn delivery_queue_create(capacity: usize) DeliveryQueue {
    return DeliveryQueue{
        .events = &[_]Event{} ** capacity,
        .capacity = capacity,
        .head = 0,
        .tail = 0,
    };
}

/// Create pending publish
pub fn pending_publish_create(event: Event) PendingPublish {
    return PendingPublish{
        .event = event,
        .retries = 0,
        .created_at = 0,
    };
}

/// Match topic against pattern
pub fn match_topic_pattern(topic: []u8, pattern: TopicPattern) TopicMatchResult {
    if (pattern.is_wildcard) {
        return topic_match_result_create(true, topic);
    }
    return topic_match_result_create(topic == pattern.pattern, topic);
}

/// Check if topic is hierarchical
pub fn is_hierarchical_topic(topic: []u8) bool {
    for (topic) |c| {
        if (c == TOPIC_SEPARATOR[0]) {
            return true;
        }
    }
    return false;
}

/// Get topic parent
pub fn get_topic_parent(topic: []u8) []u8 {
    var last_sep : usize = topic.len;
    for (0..topic.len) |i| {
        if (topic[i] == TOPIC_SEPARATOR[0]) {
            last_sep = i;
        }
    }
    if (last_sep == topic.len) {
        return "";
    }
    return topic[0..last_sep];
}

/// Get topic depth
pub fn get_topic_depth(topic: []u8) usize {
    var depth : usize = 1;
    for (topic) |c| {
        if (c == TOPIC_SEPARATOR[0]) {
            depth += 1;
        }
    }
    return depth;
}

/// Join topic parts
pub fn join_topic(parts: [][]u8) []u8 {
    if (parts.len == 0) {
        return "";
    }
    var result : []u8 = parts[0];
    for (1..parts.len) |i| {
        result = result ++ TOPIC_SEPARATOR ++ parts[i];
    }
    return result;
}

/// Split topic into parts
pub fn split_topic(topic: []u8) [][]u8 {
    var parts : [][]u8 = undefined;
    var current : []u8 = undefined;
    for (topic) |c| {
        if (c == TOPIC_SEPARATOR[0]) {
            if (current.len > 0) {
                parts = parts ++ &[_][]u8{ current };
            }
            current = &[_]u8{};
        } else {
            current = current ++ &[_]u8{ c };
        }
    }
    if (current.len > 0) {
        parts = parts ++ &[_][]u8{ current };
    }
    return parts;
}

/// Check if delivery queue is empty
pub fn is_delivery_queue_empty(queue: DeliveryQueue) bool {
    return queue.head == queue.tail;
}

/// Check if delivery queue is full
pub fn is_delivery_queue_full(queue: DeliveryQueue) bool {
    return ((queue.tail + 1) % queue.capacity) == queue.head;
}

/// Add event to delivery queue
pub fn enqueue_delivery(queue: DeliveryQueue, event: Event) DeliveryQueue {
    queue.events[queue.tail] = event;
    const new_tail = (queue.tail + 1) % queue.capacity;
    return DeliveryQueue{
        .events = queue.events,
        .capacity = queue.capacity,
        .head = queue.head,
        .tail = new_tail,
    };
}

/// Remove event from delivery queue
pub fn dequeue_delivery(queue: DeliveryQueue) DeliveryQueue {
    if (is_delivery_queue_empty(queue)) {
        return queue;
    }
    const new_head = (queue.head + 1) % queue.capacity;
    return DeliveryQueue{
        .events = queue.events,
        .capacity = queue.capacity,
        .head = new_head,
        .tail = queue.tail,
    };
}

/// Check if pattern contains wildcard
pub fn pattern_contains_wildcard(pattern: TopicPattern) bool {
    return pattern.pattern == "*" or pattern.pattern == "+" or pattern.pattern == "#";
}

/// Expand wildcard pattern to matching topics
pub fn expand_wildcard_pattern(pattern: TopicPattern, known_topics: [][]u8) [][]u8 {
    if (!pattern.is_wildcard) {
        return &[_][]u8{ pattern.pattern };
    }
    var result : [][]u8 = undefined;
    for (known_topics) |topic| {
        if (match_topic_pattern(topic, pattern).matches) {
            result = result ++ &[_][]u8{ topic };
        }
    }
    return result;
}

/// Get publish result string
pub fn publish_result_to_string(result: PublishResult) []u8 {
    if (result.success) {
        return "success";
    } else {
        return "error: " ++ result.error;
    };
}

/// Get subscribe result string
pub fn subscribe_result_to_string(result: SubscribeResult) []u8 {
    if (result.success) {
        return "success";
    } else {
        return "error: " ++ result.error;
    };
}

/// Get unsubscribe result string
pub fn unsubscribe_result_to_string(result: UnsubscribeResult) []u8 {
    if (result.success) {
        return "success";
    } else {
        return "error: " ++ result.error;
    };
}

