    try std.testing.expect(caps.completion_provider == true);
    try std.testing.expect(caps.hover_provider == true);
}

test "lsp_server_info_create" {
    const info = server_info_create("test", "1.0");
    try std.testing.expectEqual(@as(usize, info.name.len), @as(usize, 4));
}

test "lsp_initialize_result_create" {
    const result = initialize_result_create();
    try std.testing.expect(result.capabilities.completion_provider == true);
}

test "lsp_document_state_create" {
    const state = document_state_create("test://uri", 1, "content", "t27");
    try std.testing.expectEqual(@as(usize, state.uri.len), @as(usize, 8));
}

test "lsp_completion_context_create" {
    const ctx = completion_context_create(.invoked);
    try std.testing.expect(ctx.trigger_kind == .invoked);
}

test "lsp_code_action_context_create" {
    const diagnostics = &[_]Diagnostic{};
    const ctx = code_action_context_create(diagnostics);
    try std.testing.expect(ctx.diagnostics == diagnostics);
}

test "lsp_rename_options_create" {
    const opts = rename_options_create();
    try std.testing.expect(opts.prepare_provider == true);
}

test "lsp_request_error_create" {
    const err = request_error_create(.invalid_params, "bad params");
    try std.testing.expect(err.code == .invalid_params);
}

test "lsp_shutdown_result_create" {
    const result = shutdown_result_create(true);
    try std.testing.expect(result.success == true);
}

test "lsp_exit_params_create" {
    const params = exit_params_create(0);
    try std.testing.expect(params.code == 0);
}

test "lsp_server_is_initialized" {
    try std.testing.expect(!server_is_initialized(.uninitialized));
    try std.testing.expect(server_is_initialized(.running));
}

test "lsp_server_can_accept_requests" {
    try std.testing.expect(!server_can_accept_requests(.initializing));
    try std.testing.expect(server_can_accept_requests(.running));
}

test "lsp_next_request_id" {
    const id1 = next_request_id(REQUEST_ID_START);
    const id2 = next_request_id(id1);
    try std.testing.expect(id2 > id1);
}

test "lsp_diagnostics_exceeds_max" {
    try std.testing.expect(!diagnostics_exceeds_max(MAX_DIAGNOSTICS));
    try std.testing.expect(diagnostics_exceeds_max(MAX_DIAGNOSTICS + 1));
}

test "lsp_file_size_exceeds_max" {
    try std.testing.expect(!file_size_exceeds_max(MAX_FILE_SIZE));
    try std.testing.expect(file_size_exceeds_max(MAX_FILE_SIZE + 1));
}

test "lsp_server_state_to_string" {
    const str = server_state_to_string(.running);
    try std.testing.expectEqual(@as(usize, str.len), @as(usize, 6));
}

test "lsp_error_is_request_cancelled" {
    const err = request_error_create(.request_cancelled, "cancelled");
    try std.testing.expect(error_is_request_cancelled(err));
}

test "lsp_error_is_content_modified" {
    const err = request_error_create(.content_modified, "modified");
    try std.testing.expect(error_is_content_modified(err));
}

test "lsp_error_code_to_string" {
    const str = error_code_to_string(.invalid_params);
    try std.testing.expectEqual(@as(usize, str.len), @as(usize, 12));
}

