// SPDX-License-Identifier: Apache-2.0
// http.t27 — HTTP Server Specification
// HTTP listener, request/response handling, middleware
// φ² + 1/φ² = 3 | TRINITY

module server-http;

// ============================================================================
// Imports
// ============================================================================

use std;
use lsp-schema::Position;

// ============================================================================
// Constants
// ============================================================================

/// Default HTTP port
pub const DEFAULT_PORT : u16 = 8080;

/// Maximum concurrent connections
pub const MAX_CONNECTIONS : u16 = 100;

/// Request timeout in seconds
pub const REQUEST_TIMEOUT : u16 = 30;

/// HTTP GET method
pub const METHOD_GET : [3]u8 = "GET";

/// HTTP POST method
pub const METHOD_POST : [4]u8 = "POST";

/// HTTP PUT method
pub const METHOD_PUT : [3]u8 = "PUT";

/// HTTP DELETE method
pub const METHOD_DELETE : [6]u8 = "DELETE";

/// HTTP 200 OK
pub const STATUS_OK : u16 = 200;

/// HTTP 404 Not Found
pub const STATUS_NOT_FOUND : u16 = 404;

/// HTTP 500 Internal Server Error
pub const STATUS_ERROR : u16 = 500;

/// Content-Type header for JSON
pub const CONTENT_TYPE_JSON : [16]u8 = "application/json";

/// Content-Type header for SSE
pub const CONTENT_TYPE_SSE : [20]u8 = "text/event-stream";

// ============================================================================
// Types
// ============================================================================

/// HTTP method type
pub const HttpMethod = enum(u8) {
    get = 0,
    post = 1,
    put = 2,
    delete = 3,
};

/// HTTP status code with reason
pub const HttpStatus = struct {
    code : u16,
    reason : []u8,
};

/// HTTP request headers
pub const HttpHeaders = struct {
    content_type : []u8,
    content_length : usize,
    user_agent : []u8,
};

/// HTTP request
pub const HttpRequest = struct {
    method : HttpMethod,
    path : []u8,
    headers : HttpHeaders,
    body : []u8,
};

/// HTTP response
pub const HttpResponse = struct {
    status : HttpStatus,
    headers : HttpHeaders,
    body : []u8,
};

/// Server configuration
pub const ServerConfig = struct {
    host : []u8,
    port : u16,
    max_connections : u16,
    timeout_sec : u16,
};

/// Middleware context
pub const MiddlewareContext = struct {
    request : HttpRequest,
    response : ?*HttpResponse,
    metadata : []u8,
};

/// Middleware function signature
pub const Middleware = fn(MiddlewareContext) bool;

/// Server state
pub const ServerState = enum(u8) {
    stopped = 0,
    starting = 1,
    running = 2,
    stopping = 3,
};

// ============================================================================
// Functions
// ============================================================================

/// Create default server configuration
pub fn config_default() ServerConfig {
    return ServerConfig{
        .host = "127.0.0.1",
        .port = DEFAULT_PORT,
        .max_connections = MAX_CONNECTIONS,
        .timeout_sec = REQUEST_TIMEOUT,
    };
}

/// Create HTTP 200 OK response
pub fn response_ok(body: []u8) HttpResponse {
    return HttpResponse{
        .status = HttpStatus{ .code = STATUS_OK, .reason = "OK" },
        .headers = HttpHeaders{
            .content_type = CONTENT_TYPE_JSON,
            .content_length = body.len,
            .user_agent = "",
        },
        .body = body,
    };
}

/// Create HTTP 404 Not Found response
pub fn response_not_found() HttpResponse {
    return HttpResponse{
        .status = HttpStatus{ .code = STATUS_NOT_FOUND, .reason = "Not Found" },
        .headers = HttpHeaders{ .content_type = CONTENT_TYPE_JSON, .content_length = 0, .user_agent = "" },
        .body = "[]",
    };
}

/// Create HTTP 500 Internal Server Error response
pub fn response_error(message: []u8) HttpResponse {
    return HttpResponse{
        .status = HttpStatus{ .code = STATUS_ERROR, .reason = "Internal Server Error" },
        .headers = HttpHeaders{ .content_type = CONTENT_TYPE_JSON, .content_length = message.len, .user_agent = "" },
        .body = message,
    };
}

/// Create empty HTTP request
pub fn request_empty() HttpRequest {
    return HttpRequest{
        .method = .get,
        .path = "/",
        .headers = HttpHeaders{ .content_type = "", .content_length = 0, .user_agent = "" },
        .body = "",
    };
}

/// Create middleware context from request
pub fn middleware_context_create(req: HttpRequest) MiddlewareContext {
    return MiddlewareContext{
        .request = req,
        .response = null,
        .metadata = "",
    };
}

/// Check if status is success (2xx)
pub fn status_is_success(status: HttpStatus) bool {
    return status.code >= 200 and status.code < 300;
}

/// Check if status is client error (4xx)
pub fn status_is_client_error(status: HttpStatus) bool {
    return status.code >= 400 and status.code < 500;
}

/// Check if status is server error (5xx)
pub fn status_is_server_error(status: HttpStatus) bool {
    return status.code >= 500 and status.code < 600;
}

/// Create HTTP GET request for path
pub fn request_get(path: []u8) HttpRequest {
    return HttpRequest{
        .method = .get,
        .path = path,
        .headers = HttpHeaders{ .content_type = "", .content_length = 0, .user_agent = "" },
        .body = "",
    };
}

/// Create HTTP POST request with body
pub fn request_post(path: []u8, body: []u8) HttpRequest {
    return HttpRequest{
        .method = .post,
        .path = path,
        .headers = HttpHeaders{
            .content_type = CONTENT_TYPE_JSON,
            .content_length = body.len,
            .user_agent = "",
        },
        .body = body,
    };
}

/// Get method as string
pub fn method_to_string(method: HttpMethod) []u8 {
    return switch (method) {
        .get => METHOD_GET,
        .post => METHOD_POST,
        .put => METHOD_PUT,
        .delete => METHOD_DELETE,
    };
}

/// Check if content type is JSON
pub fn is_json_content(content_type: []u8) bool {
    return std.mem.eql(content_type, CONTENT_TYPE_JSON);
}

/// Check if content type is SSE
pub fn is_sse_content(content_type: []u8) bool {
    return std.mem.eql(content_type, CONTENT_TYPE_SSE);
}

