// SPDX-License-Identifier: Apache-2.0
// t27/specs/numeric/requant_boundary.t27
// Activation requantizer: the threshold boundary convention.
//
// Recorded because Wave 669 had to settle a semantic question with no
// specification to appeal to. Two independently written implementations of the
// same rule -- the emitted `activation_requant` RTL and the end-to-end
// testbench reference in sim/tb_data_check.v -- agreed everywhere except at
// acc == +-threshold, and nothing in specs/ said which was right.
module RequantBoundary {
    const MUTANT : i32 = -1;
    const MUTANT2 : i32 = -2;
    const MUTANT3 : i32 = -3;

// 1. Encoding
// Claim ID: C-requant-000 (PRE_RULE, mirrors the emitted localparams)

    // Balanced trit codes. 0b11 is reserved and must never be produced;
    // an unreachability property for it already exists in the RTL.
    const TRIT_N : u2 = 0b00;          // -1
    const TRIT_Z : u2 = 0b01;          //  0
    const TRIT_P : u2 = 0b10;          // +1
    const TRIT_RESERVED : u2 = 0b11;   // never produced

// 2. The boundary convention
// Claim ID: C-requant-001 (VERIFIED_SW, [simulated] -- NOT measured on FPGA)
//
// The boundary is INCLUSIVE on both sides. Provenance: PRE_RULE -- this value
// was fixed before this spec existed, stated in the RTL as a documented
// priority chain and asserted by activation_requant's own inline properties.
// Matching it here is therefore a RECORD, not independent evidence.
//
// A PRIORITY CHAIN, not parallel comparisons: a host may program a negative
// threshold, which makes both comparisons true at once. The chain keeps the
// output inside the legal alphabet for every input rather than relying on a
// precondition the host might not honour. That decision predates this spec.

    fn requantize(acc: i16, threshold: i16) -> u2 {
        if acc >= threshold {
            return TRIT_P;
        }
        if acc <= -threshold {
            return TRIT_N;
        }
        return TRIT_Z;
    }

// 3. Consequence of the chain under a negative threshold
// Claim ID: C-requant-002 (VERIFIED_SW by reading + inline properties;
//                          NO VECTOR -- see scope limits below)
//
// Not a claim that a negative threshold is meaningful. A claim that it cannot
// produce TRIT_RESERVED or an ambiguous encoding: the first arm wins.

    fn negative_threshold_yields_p(acc: i16, threshold: i16) -> bool {
        if threshold < 0 {
            return requantize(acc, threshold) == TRIT_P;
        }
        return true;
    }

// 4. Verification record
// Claim ID: C-requant-003 (VERIFIED_SW, [simulated])
//
// 26 configurations, engine output against a reference computed inside the
// testbench, via `python3 formal/value_sweep.py`. All 26 matched.
//
// Seeds 5 and 7 land on acc == -threshold EXACTLY. Before Wave 669 no vector
// in this campaign ever reached the boundary, because every input and weight
// was +1 and the accumulator was therefore always 27*chunks -- never within 24
// of the threshold. A boundary disagreement is visible only from the boundary.

    const VERIFY_CHECKED : u32 = 26;
    const VERIFY_MATCHED : u32 = 26;
    const VERIFY_BOUNDARY_REACHED : bool = true;
    const VERIFY_ACC_MIN_OBSERVED : i16 = -6;
    const VERIFY_ACC_MAX_OBSERVED : i16 = 81;

// 5. Finding F-requant-001 (RESOLVED)
//
// The testbench reference used strict `>` and `<`. It agreed with the design at
// every other accumulator value in the observed range. The REFERENCE was
// corrected, not the design.
//
// The adjudication is recorded because the direction matters more than the
// outcome: there was no authority above the two implementations. The design's
// convention is stated twice in the artifact -- RTL chain plus inline
// properties -- and the reference agreed with neither. Had the intended
// semantics been exclusive, the same evidence would have condemned the design.
// This module now supplies the authority that was missing, so a future
// disagreement is decidable without re-running the argument.

    const FINDING_SITE : str = "sim/tb_data_check.v ref_trit()";
    const FINDING_RESOLVED : bool = true;

// 6. Open question Q-requant-001 -- DO NOT GUESS
//
// Is INCLUSIVE the INTENDED semantics, or merely the implemented one? This
// module records what the artifact does and that its two internal statements
// agree. It does NOT establish that a BitNet-style requantizer ought to round
// at the boundary this way rather than the other, and no source in this
// repository settles it. Owner: author.

    const OPEN_QUESTION_DO_NOT_GUESS : bool = true;

// 7. Scope limits -- what this module does NOT establish
//
//   * measured on FPGA -- every result here is [simulated] only
//   * the semantic intent behind the boundary (Q-requant-001)
//   * thresholds other than 3 -- the sweep holds threshold fixed, because
//     varying it exercises the testbench's arithmetic rather than the design
//   * negative thresholds -- C-requant-002 is read from the RTL and its inline
//     properties and has NO vector in the sweep
//   * accumulator values outside [-6, +81], the observed range

    const SUPERIORITY_CLAIMED : bool = false;
    const MEASURED_ON_FPGA : bool = false;

// 8. Tests
//
// These execute the rule stated above. They are a RECORD of the convention in
// section 2, not independent evidence for it: the same author wrote both. What
// they do buy is that a silent change to `requantize` can no longer pass.

    // The three legal codes are distinct, and none of them is the reserved one.
    test trit_alphabet_is_distinct
        then TRIT_N != TRIT_Z
        and TRIT_Z != TRIT_P
        and TRIT_N != TRIT_P
        and TRIT_N != TRIT_RESERVED
        and TRIT_Z != TRIT_RESERVED
        and TRIT_P != TRIT_RESERVED

    // C-requant-001. The boundary itself, both sides, at threshold 3 -- the
    // exact points where the testbench reference disagreed (F-requant-001).
    test boundary_is_inclusive_both_sides
        then requantize(3, 3) == TRIT_P
        and requantize(-3, 3) == TRIT_N

    // One step inside the boundary is zero on both sides.
    test just_inside_boundary_is_zero
        then requantize(2, 3) == TRIT_Z
        and requantize(-2, 3) == TRIT_Z
        and requantize(0, 3) == TRIT_Z

    // One step outside keeps the sign.
    test just_outside_boundary_saturates
        then requantize(4, 3) == TRIT_P
        and requantize(-4, 3) == TRIT_N

    // Symmetry about zero for a positive threshold: -acc maps to the mirror
    // code of acc.
    test positive_threshold_is_symmetric
        then requantize(7, 3) == TRIT_P
        and requantize(-7, 3) == TRIT_N
        and requantize(1, 3) == TRIT_Z
        and requantize(-1, 3) == TRIT_Z

    // The extremes of the range the sweep actually observed, [-6, +81].
    test observed_range_endpoints
        then requantize(VERIFY_ACC_MIN_OBSERVED, 3) == TRIT_N
        and requantize(VERIFY_ACC_MAX_OBSERVED, 3) == TRIT_P

    // C-requant-002, the part that holds. A negative threshold makes both
    // comparisons true only on the OVERLAP [threshold, -threshold]; there the
    // chain's first arm wins, exactly as claimed.
    test negative_threshold_takes_the_first_arm_on_the_overlap
        then requantize(-1, -1) == TRIT_P
        and requantize(0, -1) == TRIT_P
        and requantize(1, -1) == TRIT_P
        and negative_threshold_yields_p(0, -1) == true

    // C-requant-002, the part that holds. Below the negative threshold the
    // arms no longer overlap: the first is false, the second is true, and the
    // code is N. Still inside the legal alphabet -- never TRIT_RESERVED, which
    // is what section 3's prose actually claims.
    test negative_threshold_stays_inside_the_alphabet
        then requantize(-100, -1) == TRIT_N
        and requantize(-100, -1) != TRIT_RESERVED
        and requantize(100, -1) == TRIT_P
        and requantize(100, -1) != TRIT_RESERVED

    // FINDING F-requant-002 (OPEN). This test FAILS, and it is meant to.
    //
    // `negative_threshold_yields_p` guards on `threshold < 0` alone and then
    // asserts TRIT_P, i.e. it states that ANY negative threshold yields P for
    // ANY accumulator. It does not. For acc < threshold < 0 only the second arm
    // is true and the code is N: acc = -100, threshold = -1 returns false.
    //
    // Section 3's prose claim -- "it cannot produce TRIT_RESERVED" -- is sound
    // and is covered by the test above. The FUNCTION encodes a stronger claim
    // than the prose and that stronger claim is false. The predicate needs the
    // overlap condition `acc >= threshold` in its guard, or the claim needs
    // restating. Deciding which is the author's call, so the test is left
    // failing rather than weakened to match the code.
    test negative_threshold_yields_p_holds_universally
        then negative_threshold_yields_p(-100, -1) == true

    // The guard: for a non-negative threshold the predicate is vacuously true
    // and says nothing about the code produced.
    test negative_threshold_predicate_is_vacuous_when_non_negative
        then negative_threshold_yields_p(0, 3) == true
        and negative_threshold_yields_p(81, 3) == true

    // At threshold 0 the two arms tile the whole range and TRIT_Z is
    // unreachable: acc >= 0 takes the first arm, acc < 0 satisfies acc <= -0.
    test zero_threshold_leaves_no_dead_zone
        then requantize(0, 0) == TRIT_P
        and requantize(1, 0) == TRIT_P
        and requantize(-1, 0) == TRIT_N

    // Section 4's own record: every configuration checked also matched.
    test verification_record_is_complete
        then VERIFY_CHECKED == VERIFY_MATCHED
        and VERIFY_BOUNDARY_REACHED == true
}

// Timing closure - critical path analysis and optimization
// Tests timing analysis and pipeline insertion strategies

module TimingClosure {
    use base::types;

    // Timing grades
    const TIMING_PASS: u32 = 0;
    const TIMING_MARGINAL: u32 = 1;
    const TIMING_FAIL: u32 = 2;

    // Pipeline stages
    const MIN_PIPELINE: u32 = 1;
    const MAX_PIPELINE: u32 = 8;

    // Target frequencies (in MHz)
    const TARGET_FREQ_LOW: u32 = 25;
    const TARGET_FREQ_MID: u32 = 50;
    const TARGET_FREQ_HIGH: u32 = 100;

    // Critical path info (packed: [delay:16][stages:8][slack:8])
    fn create_critical_path(delay: u32, stages: u32, slack: u32) -> u32 {
        return (((delay & 0xFFFF) << 16) | 
                ((stages & 0xFF) << 8) | 
                (slack & 0xFF));
    }

    fn extract_delay(path: u32) -> u32 {
        return ((path >> 16) & 0xFFFF);
    }

    fn extract_stages(path: u32) -> u32 {
        return ((path >> 8) & 0xFF);
    }

    fn extract_slack(path: u32) -> u32 {
        return (path & 0xFF);
    }

    // Timing grade based on slack
    fn grade_timing(slack: u32) -> u32 {
        // slack carries a two's-complement value: MSB set means negative slack.
        if (slack > 0x7FFFFFFF) {
            return TIMING_FAIL;
        } else if (slack >= 100) {
            return TIMING_PASS;
        } else {
            return TIMING_MARGINAL;
        }
    }

    // Calculate required pipeline stages for target frequency
    fn calculate_pipeline_stages(delay: u32, target_freq: u32) -> u32 {
        // Period = 1000 / freq (MHz), stages = delay / period
        if (target_freq == 0) {
            return MAX_PIPELINE;
        }

        if ((1000 / target_freq) == 0) {
            return MAX_PIPELINE;
        }

        if ((delay / (1000 / target_freq)) < MIN_PIPELINE) {
            return MIN_PIPELINE;
        }
        if ((delay / (1000 / target_freq)) > MAX_PIPELINE) {
            return MAX_PIPELINE;
        }
        return (delay / (1000 / target_freq));
    }

    // Check if retiming needed
    fn retiming_needed(current_slack: u32, threshold: u32) -> bool {
        return (current_slack < threshold);
    }

    // Register balancing decision
    fn balance_registers(stage_delay: u32, target_period: u32) -> bool {
        return (stage_delay > (target_period * 2));
    }

    // Critical path comparison
    fn compare_critical_paths(path1: u32, path2: u32) -> u32 {
        if (extract_delay(path1) > extract_delay(path2)) {
            return path1;
        } else {
            return path2;
        }
    }

    // Timing report (packed: [grade:2][freq:10][paths:20])
    fn create_timing_report(grade: u32, max_freq: u32, critical_paths: u32) -> u32 {
        return (((grade & 0x3) << 30) | 
                ((max_freq & 0x3FF) << 20) | 
                (critical_paths & 0xFFFFF));
    }

    fn extract_grade(report: u32) -> u32 {
        return ((report >> 30) & 0x3);
    }

    fn extract_max_freq(report: u32) -> u32 {
        return ((report >> 20) & 0x3FF);
    }

    fn extract_critical_paths(report: u32) -> u32 {
        return (report & 0xFFFFF);
    }

    // Check if timing closure achieved
    fn timing_closure_achieved(report: u32, target_freq: u32) -> bool {
        return (extract_grade(report) == TIMING_PASS) && 
               (extract_max_freq(report) >= target_freq);
    }

    // ---- Tests ----

    test create_critical_path_correct {
        path = create_critical_path(500, 3, 100);
        assert(extract_delay(path) == 500, "delay");
        assert(extract_stages(path) == 3, "stages");
        assert(extract_slack(path) == 100, "slack");
    }

    test grade_timing_pass {
        grade = grade_timing(150);
        assert(grade == TIMING_PASS, "positive slack = pass");
    }

    test grade_timing_marginal {
        grade = grade_timing(50);
        assert(grade == TIMING_MARGINAL, "low slack = marginal");
    }

    test grade_timing_fail {
        grade = grade_timing(0xFFFFFFFF - 50); // Large unsigned = negative signed
        assert(grade == TIMING_FAIL, "negative = fail");
    }

    test calculate_pipeline_stages_needed {
        // Delay 500ns, target 50MHz (period 20ns)
        // 500 / 20 = 25 stages, but capped at MAX
        stages = calculate_pipeline_stages(500, 50);
        assert(stages == MAX_PIPELINE, "capped at max");
    }

    test calculate_pipeline_stages_few {
        // Delay 40ns, target 50MHz (period 20ns)
        // 40 / 20 = 2 stages
        stages = calculate_pipeline_stages(40, 50);
        assert(stages == 2, "2 stages needed");
    }

    test calculate_pipeline_stages_zero_freq {
        stages = calculate_pipeline_stages(100, 0);
        assert(stages == MAX_PIPELINE, "zero freq = max stages");
    }

    test retiming_needed_yes {
        assert(retiming_needed(10, 100) == true, "slack < threshold");
    }

    test retiming_needed_no {
        assert(retiming_needed(150, 100) == false, "slack >= threshold");
    }

    test balance_registers_yes {
        assert(balance_registers(50, 20) == true, "delay > 2x period");
    }

    test balance_registers_no {
        assert(balance_registers(15, 20) == false, "delay <= 2x period");
    }

    test compare_critical_paths_first {
        path1 = create_critical_path(500, 3, 50);
        path2 = create_critical_path(300, 2, 100);
        result = compare_critical_paths(path1, path2);
        assert(extract_delay(result) == 500, "first is longer");
    }

    test compare_critical_paths_second {
        path1 = create_critical_path(300, 2, 100);
        path2 = create_critical_path(500, 3, 50);
        result = compare_critical_paths(path1, path2);
        assert(extract_delay(result) == 500, "second is longer");
    }

    test create_timing_report_correct {
        report = create_timing_report(0, 100, 5);
        assert(extract_grade(report) == 0, "grade");
        assert(extract_max_freq(report) == 100, "frequency");
        assert(extract_critical_paths(report) == 5, "paths");
    }

    test timing_closure_achieved_yes {
        report = create_timing_report(TIMING_PASS, 75, 3);
        assert(timing_closure_achieved(report, 50) == true, "pass + freq met");
    }

    test timing_closure_achieved_no_grade {
        report = create_timing_report(TIMING_FAIL, 75, 3);
        assert(timing_closure_achieved(report, 50) == false, "grade fail");
    }

    test timing_closure_achieved_no_freq {
        report = create_timing_report(TIMING_PASS, 40, 3);
        assert(timing_closure_achieved(report, 50) == false, "freq not met");
    }

    test extract_slack_negative_handling {
        // Slack field is 8-bit; 0xFF is the two's-complement negative marker.
        path = create_critical_path(500, 3, 0xFF);
        slack = extract_slack(path);
        assert(slack == 0xFF, "extracted large slack");
    }
}

// TRI-NET compute safety gate: the single no-double-pay invariant that composes
// the three independent guards the stack grew -- freshness (tri_a2a.is_fresh,
// anti-replay), finiteness (tri_compute_settle.is_finite_gf16, no inf/nan garbage),
// and settled-once (a request pays at most one time). A reward is minted ONLY when
// all three hold. This is the choke point that makes double-pay, replay-pay, and
// garbage-pay impossible in one place, rather than relying on each ring separately.

module TriComputeSafety {
    use base::types;

    // Payable iff: not already settled AND fresh AND finite. (1 = yes, 0 = no.)
    fn payable(fresh: u32, finite: u32, already_settled: u32) -> u32 {
        if (already_settled == 1) {
            return 0;
        } else {
            if (fresh == 1) {
                if (finite == 1) {
                    return 1;
                } else {
                    return 0;
                }
            } else {
                return 0;
            }
        }
    }

    // Mint the reward only through the gate; otherwise zero.
    fn reward_gate(base_reward: u32, fresh: u32, finite: u32, already_settled: u32) -> u32 {
        if (payable(fresh, finite, already_settled) == 1) {
            return base_reward;
        } else {
            return 0;
        }
    }

    // The stack grew a FOURTH mint-time guard since this gate was written: a receipt
    // must carry a VALID executor signature (tri_compute_settle.settle_signed sets
    // sig_ok via ed25519-dalek). Without it, a FORGED receipt that happens to be
    // fresh + finite + new would mint -- the forgery vector this choke point claimed
    // to close but did not. payable_authentic is the complete gate: authentic AND
    // the original three. A valid signature never bypasses freshness/finiteness/
    // settled-once; a missing one closes the gate regardless of them.
    fn payable_authentic(sig_ok: u32, fresh: u32, finite: u32, already_settled: u32) -> u32 {
        if (sig_ok == 1) {
            return payable(fresh, finite, already_settled);
        } else {
            return 0;
        }
    }

    fn reward_gate_authentic(base_reward: u32, sig_ok: u32, fresh: u32, finite: u32, already_settled: u32) -> u32 {
        if (payable_authentic(sig_ok, fresh, finite, already_settled) == 1) {
            return base_reward;
        } else {
            return 0;
        }
    }

    // ---- Tests / invariants ----

    // No double pay: a receipt already settled pays nothing, even if fresh+finite.
    test no_double_pay {
        assert(reward_gate(16, 1, 1, 1) == 0, "already-settled receipt pays nothing");
    }

    // No replay pay: a stale (non-fresh) receipt pays nothing.
    test replay_pays_nothing {
        assert(reward_gate(16, 0, 1, 0) == 0, "stale/replayed receipt pays nothing");
    }

    // No garbage pay: an inf/nan (non-finite) result pays nothing.
    test garbage_pays_nothing {
        assert(reward_gate(16, 1, 0, 0) == 0, "inf/nan result pays nothing");
    }

    // The honest path pays exactly once: fresh + finite + not-yet-settled.
    test honest_path_pays {
        assert(reward_gate(16, 1, 1, 0) == 16, "fresh + finite + new pays the reward");
        assert(payable(1, 1, 0) == 1, "the gate opens only on the honest path");
    }

    // The gate is the AND of all three guards: dropping any one closes it.
    test gate_needs_all_three {
        assert(payable(0, 1, 0) == 0, "not fresh -> closed");
        assert(payable(1, 0, 0) == 0, "not finite -> closed");
        assert(payable(1, 1, 1) == 0, "already settled -> closed");
        assert(payable(1, 1, 0) == 1, "all three -> open");
    }

    // No forgery pay: a FORGED receipt (no valid signature) mints nothing even when
    // it is fresh + finite + not-yet-settled -- the hole the 3-guard gate left open.
    test forgery_pays_nothing {
        assert(reward_gate_authentic(16, 0, 1, 1, 0) == 0, "unsigned/forged receipt pays nothing despite fresh+finite+new");
        assert(payable_authentic(0, 1, 1, 0) == 0, "no valid signature -> gate closed");
    }

    // The authentic gate is the AND of ALL FOUR guards: signature, freshness,
    // finiteness, settled-once. A valid signature never bypasses the other three.
    test authentic_gate_needs_all_four {
        assert(reward_gate_authentic(16, 1, 1, 1, 0) == 16, "sig + fresh + finite + new -> pays");
        assert(payable_authentic(1, 0, 1, 0) == 0, "valid sig but stale -> closed");
        assert(payable_authentic(1, 1, 0, 0) == 0, "valid sig but inf/nan -> closed");
        assert(payable_authentic(1, 1, 1, 1) == 0, "valid sig but already settled -> closed");
        assert(payable_authentic(1, 1, 1, 0) == 1, "all four -> open");
    }

    // payable_authentic is a strict subset of payable: it never opens where payable
    // is closed, and additionally requires the signature.
    test authentic_is_stricter {
        assert(payable_authentic(1, 1, 1, 0) == payable(1, 1, 0), "with a valid sig it matches payable exactly");
        assert(payable_authentic(0, 1, 1, 0) == 0, "without the sig it is strictly stricter");
    }
}

// SPDX-License-Identifier: Apache-2.0
; 06 — Structs, enums, and switch
; Lesson 6. Grouping fields, naming a fixed set of states, and choosing
; between them.
; .
; The important rule in this file: `switch` is an EXPRESSION here. The
; statement form parses without complaint and then discards the body of the
; function containing it, emitting a panic stub instead. Nothing warns you.
; Always write `return switch (x) { ... };`.
; phi^2 + 1/phi^2 = 3 | TRINITY

module tutorial-06-structs;

pub const TRIT_NEG : i8 = -1;
pub const TRIT_ZERO : i8 = 0;
pub const TRIT_POS : i8 = 1;

// ============================================================================
// Structs
//
// `packed` fixes the layout: fields sit adjacent in declaration order with no
// padding inserted. For anything that becomes a register or crosses a bus,
// that is the point -- an unpacked layout is the compiler's choice, and a
// spec should not be making the reader guess.
// ============================================================================

pub const Sample = packed struct {
    value : i8,
    valid : bool,
};

// Only one struct in this module, and that is deliberate. A second `packed
// struct` in the same module currently breaks the Verilog-from-HIR backend:
//
//     HIR validation failed: duplicate signal name:
//
// Note the name is empty. Bisected to exactly this -- one struct emits, two
// collide, regardless of whether their field names differ; enums are
// unaffected, and a struct beside an enum is fine. Six real specs in the
// corpus are stuck on it (chips/*/specs/fpga/gf16_to_fp16.t27 and
// gf32_to_fp32.t27, each declaring two structs). Filed as t27#3283.
//
// The other four backends are unaffected, so this bites only if you target
// Verilog through HIR. Until it is fixed, one struct per module.

// ── Building one ────────────────────────────────────────────────────────────
// `Type{ .field = value }` -- the leading dot names the field.
pub fn make_sample(value: i8) Sample {
    return Sample{ .value = value, .valid = true };
}

pub fn empty_sample() Sample {
    return Sample{ .value = TRIT_ZERO, .valid = false };
}

// ── Reading one ─────────────────────────────────────────────────────────────
pub fn sample_value(s: Sample) i8 {
    return s.value;
}

pub fn sample_is_valid(s: Sample) bool {
    return s.valid;
}

// ============================================================================
// Enums
//
// A fixed set of named states, with the backing integer type written out.
// ============================================================================

pub const Trit = enum(i8) {
    Negative,
    Zero,
    Positive,
};

pub const Rounding = enum(u8) {
    TowardZero,
    TowardNearest,
    TowardPositive,
    TowardNegative,
};

// ============================================================================
// switch — expression form only
//
// Each arm is `pattern => value,` and `else` catches the rest. The whole thing
// produces a value, so it is returned or bound, never left standing alone.
// ============================================================================

pub fn trit_to_number(t: i8) i8 {
    return switch (t) {
        0 => TRIT_ZERO,
        1 => TRIT_POS,
        else => TRIT_NEG,
    };
}

pub fn rounding_bias(mode: u8) u8 {
    return switch (mode) {
        0 => 0,
        1 => 128,
        2 => 255,
        else => 0,
    };
}

// A switch bound to a local reads well when the result feeds further work.
pub fn describe_width(bits: u8) u8 {
    const category = switch (bits) {
        8 => 1,
        16 => 2,
        32 => 3,
        else => 0,
    };
    return category;
}

// ============================================================================
// Tests
// ============================================================================

test "a struct literal round-trips through its fields" {
    const s = make_sample(TRIT_POS);
    try std.testing.expectEqual(@as(i8, TRIT_POS), sample_value(s));
    try std.testing.expect(sample_is_valid(s));
    try std.testing.expect(!sample_is_valid(empty_sample()));
}

test "switch covers its arms and falls through to else" {
    try std.testing.expectEqual(@as(i8, TRIT_ZERO), trit_to_number(0));
    try std.testing.expectEqual(@as(i8, TRIT_POS), trit_to_number(1));
    try std.testing.expectEqual(@as(i8, TRIT_NEG), trit_to_number(7));
}

test "describe_width maps known widths and defaults the rest" {
    try std.testing.expectEqual(@as(u8, 1), describe_width(8));
    try std.testing.expectEqual(@as(u8, 3), describe_width(32));
    try std.testing.expectEqual(@as(u8, 0), describe_width(7));
}

// SPDX-License-Identifier: Apache-2.0
; hello_world.t27 -- start here
; The smallest spec that still shows every part of the language: constants,
; a type, functions, a test and an invariant. Read it top to bottom, then
; watch it become tokens, an AST, and five different target languages.
; phi^2 + 1/phi^2 = 3 | TRINITY

module hello-world;

// ============================================================================
// Constants
//
// A spec is a source of truth, so the numbers it fixes are named. `pub` makes
// a name visible to other specs; the type after `:` is not optional.
// ============================================================================

pub const GREETING_LEN : u8 = 5;
pub const TRINITY : i8 = 3;

; A trit is the unit this language is built on: three states, not two.
pub const TRIT_NEG : i8 = -1;
pub const TRIT_ZERO : i8 = 0;
pub const TRIT_POS : i8 = 1;

// ============================================================================
// Types
//
// A struct groups named fields. Every field carries its own width, because a
// spec has to say what reaches hardware, not leave it to a compiler default.
// ============================================================================

pub const Greeting = packed struct {
    length : u8,
    trit : i8,
};

// ============================================================================
// Functions
//
// A function declares its parameter types and its return type. There is no
// inference here either -- the signature is part of the specification.
// ============================================================================

; Add two trits and clamp the result back into {-1, 0, +1}.
; Saturation, not wrap-around: a trit that overflows stays at the rail.
pub fn trit_add(a: i8, b: i8) i8 {
    const sum = a + b;
    if (sum > TRIT_POS) {
        return TRIT_POS;
    }
    if (sum < TRIT_NEG) {
        return TRIT_NEG;
    }
    return sum;
}

; The multiplicative identity of the trit set: multiplying by zero gives zero,
; and the sign rule is the ordinary one.
pub fn trit_mul(a: i8, b: i8) i8 {
    return a * b;
}

; Build the struct above from a length and a trit.
pub fn greeting_new(length: u8, trit: i8) Greeting {
    return Greeting{ .length = length, .trit = trit };
}

// ============================================================================
// Tests
//
// Tests live beside the thing they describe and are emitted into every target
// that supports them, so the same claim is checked in each language.
// ============================================================================

test "trit_add saturates instead of wrapping" {
    try std.testing.expectEqual(@as(i8, TRIT_POS), trit_add(TRIT_POS, TRIT_POS));
    try std.testing.expectEqual(@as(i8, TRIT_NEG), trit_add(TRIT_NEG, TRIT_NEG));
    try std.testing.expectEqual(@as(i8, TRIT_ZERO), trit_add(TRIT_POS, TRIT_NEG));
}

test "trit_mul follows the ordinary sign rule" {
    try std.testing.expectEqual(@as(i8, TRIT_POS), trit_mul(TRIT_NEG, TRIT_NEG));
    try std.testing.expectEqual(@as(i8, TRIT_NEG), trit_mul(TRIT_NEG, TRIT_POS));
    try std.testing.expectEqual(@as(i8, TRIT_ZERO), trit_mul(TRIT_ZERO, TRIT_POS));
}

// ============================================================================
// Invariants
//
// An invariant is a claim that must hold for the whole module rather than for
// one example. This is the part a test cannot express on its own.
// ============================================================================

invariant trit_set_is_three
    assert TRIT_POS - TRIT_NEG == TRINITY - 1

invariant greeting_length_is_fixed
    assert GREETING_LEN == 5
